/**
 * Curated drug pharmacokinetic database.
 *
 * Half-life values originally auto-generated from PubChem PUGView.
 * Duration / interval values curated per drug from DailyMed FDA SPLs
 * and PubChem PUGView — see docs/DRUGS.md for the full per-drug evidence
 * and docs/duration-research.md for raw source quotes.
 *
 * Source of half-life data: PubChem PUGView REST API
 * Source of duration / interval data: DailyMed FDA SPLs (§2, §12.2, §14)
 *   + selected PubChem PUGView quotes — see docs/DRUGS.md.
 */

export type DurationType = 'action' | 'interval' | 'none';

export interface DrugEntry {
  /** Lowercase generic name + formulation suffix (for search matching). */
  id: string;
  /** Generic name without formulation suffix — links variants of the same drug. */
  baseDrugId: string;
  /** Display name (may include formulation, e.g. "Methylphenidate ER (Concerta)"). */
  name: string;
  /** Brand names. */
  brands: string[];
  /**
   * Formulation:
   *   IR  = immediate release (default)
   *   ER / XR / SR / CR / XL / LA = modified-release (labelling varies by brand)
   *   OROS = osmotic-release oral system (Concerta)
   *   patch / sublingual / IV / topical = non-oral routes
   */
  formulation:
    | 'IR'
    | 'ER'
    | 'XR'
    | 'SR'
    | 'CR'
    | 'XL'
    | 'LA'
    | 'OROS'
    | 'patch'
    | 'sublingual'
    | 'IV'
    | 'topical';
  /** Half-life in minutes (midpoint of typical range, formulation-specific). */
  halfLifeMinutes: number;
  /** Human-readable half-life range. */
  halfLifeLabel: string;
  /**
   * Duration of action OR dosing interval, in minutes, per docs/DRUGS.md classification.
   *   - durationType='action'   → this value is "Duration of action"
   *   - durationType='interval' → this value is "Dosing interval" (or "Maintenance dosing interval" if isMaintenanceInterval)
   *   - durationType='none'     → value is null; UI hides the third timer.
   * Snapshotted onto pills/doses at creation so later DB revisions don't mutate history.
   */
  durationOfActionMinutes: number | null;
  /** Controls the third-timer label and visibility. See docs/DRUGS.md. */
  durationType: DurationType;
  /** If true (interval only), render label as "Maintenance dosing interval". */
  isMaintenanceInterval?: boolean;
  /** If true, UI must render a weekly-dosing warning (methotrexate — daily dosing is lethal). */
  requiresWeeklyWarning?: boolean;
  /** Common dosage in mg. */
  commonDosageMg: number;
  /** Drug category. */
  category: string;
}

