/**
 * Typeahead search over curated drugs. Matches against name + brands (case-insensitive).
 * Orders exact prefix matches before substring matches, capped at `limit`.
 */
export function searchDrugs(query: string, limit: number = 20): DrugEntry[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];

  const prefix: DrugEntry[] = [];
  const contains: DrugEntry[] = [];

  for (const drug of DRUG_DATABASE) {
    const haystacks = [drug.name.toLowerCase(), ...drug.brands.map((b) => b.toLowerCase())];
    if (haystacks.some((h) => h.startsWith(q))) {
      prefix.push(drug);
    } else if (haystacks.some((h) => h.includes(q))) {
      contains.push(drug);
    }
  }

  return [...prefix, ...contains].slice(0, limit);
}
